    testRoundTripConversion(expected, "message myrecord {\n" + "  required int64 timestamp (TIMESTAMP(MILLIS,true));\n" + "}\n");
    // Test that conversions for timestamp types only use APIs that are available in the user's Avro version
    for (String avroVersion : ImmutableSet.of("1.7.0", "1.8.0", "1.9.0", "1.10.0", "1.11.0")) {
        Mockito.when(AvroRecordConverter.getRuntimeAvroVersion()).thenReturn(avroVersion);
        final Schema converted = new AvroSchemaConverter().convert(Types.buildMessage().addField(Types.primitive(INT64, Type.Repetition.REQUIRED).as(LogicalTypeAnnotation.timestampType(false, LogicalTypeAnnotation.TimeUnit.MILLIS)).length(1).named("timestamp_type")).named("TestAvro"));
        assertEquals(avroVersion.matches("1\\.[789]\\.\\d+") ? "timestamp-millis" : "local-timestamp-millis", converted.getField("timestamp_type").schema().getLogicalType().getName());
    }
    for (PrimitiveTypeName primitive : new PrimitiveTypeName[] { INT32, INT96, FLOAT, DOUBLE, BOOLEAN, BINARY, FIXED_LEN_BYTE_ARRAY }) {
        final PrimitiveType type;
        if (primitive == FIXED_LEN_BYTE_ARRAY) {
            type = new PrimitiveType(REQUIRED, primitive, 12, "test", TIMESTAMP_MILLIS);
        } else {
            type = new PrimitiveType(REQUIRED, primitive, "test", TIMESTAMP_MILLIS);
        }
        assertThrows("Should not allow TIMESTAMP_MILLIS with " + primitive, IllegalArgumentException.class, () -> new AvroSchemaConverter().convert(message(type)));
    }
}

