@Test
public void testReadWrite() throws Exception {
    final Configuration conf = new Configuration();
    final Path inputPath = new Path("src/test/java/org/apache/parquet/avro/TestInputOutputFormat.java");
    final Path parquetPath = new Path("target/test/hadoop/TestInputOutputFormat/parquet");
    final Path outputPath = new Path("target/test/hadoop/TestInputOutputFormat/out");
    final FileSystem fileSystem = parquetPath.getFileSystem(conf);
    fileSystem.delete(parquetPath, true);
    fileSystem.delete(outputPath, true);
    {
        final Job job = new Job(conf, "write");
        // input not really used
        TextInputFormat.addInputPath(job, inputPath);
        job.setInputFormatClass(TextInputFormat.class);
        job.setMapperClass(TestInputOutputFormat.MyMapper.class);
        job.setNumReduceTasks(0);
        job.setOutputFormatClass(AvroParquetOutputFormat.class);
        AvroParquetOutputFormat.setOutputPath(job, parquetPath);
        AvroParquetOutputFormat.setSchema(job, avroSchema);
        waitForJob(job);
    }
    {
        final Job job = new Job(conf, "read");
        job.setInputFormatClass(AvroParquetInputFormat.class);
        AvroParquetInputFormat.setInputPaths(job, parquetPath);
        job.setMapperClass(TestInputOutputFormat.MyMapper2.class);
        job.setNumReduceTasks(0);
        job.setOutputFormatClass(TextOutputFormat.class);
        TextOutputFormat.setOutputPath(job, outputPath);
        waitForJob(job);
    }
    try (final BufferedReader out = new BufferedReader(new FileReader(new File(outputPath.toString(), "part-m-00000")))) {
        String lineOut;
        int lineNumber = 0;
        while ((lineOut = out.readLine()) != null) {
            lineOut = lineOut.substring(lineOut.indexOf("\t") + 1);
            GenericRecord a = nextRecord(lineNumber == 4 ? null : lineNumber);
            assertEquals("line " + lineNumber, a.toString(), lineOut);
            ++lineNumber;
        }
        assertNull("line " + lineNumber, out.readLine());
    }
}

@Test
public void testUnshredded() throws Exception {
    // Unshredded Variant should produce exactly the same value and metadata.
    Variant testValue = fullVariant(b -> {
        VariantObjectBuilder ob = b.startObject();
        ob.appendKey("a");
        ob.appendLong(123);
        ob.appendKey("b");
        VariantArrayBuilder ab = ob.startArray();
        ab.appendString("a");
        ab.appendLong(2);
        ab.appendBoolean(true);
        ab.appendNull();
        ob.endArray();
        b.endObject();
    });
    Binary expectedValue = Binary.fromConstantByteBuffer(testValue.getValueBuffer());
    Binary expectedMetadata = Binary.fromConstantByteBuffer(testValue.getMetadataBuffer());
    // Test with value before metadata in the schema: Spark's initial implementation wrote in this
    // order. The read schema (set below) requires metadata before value, but the order in the file
    // schema shouldn't matter.
    Path test = writeDirect("message VariantMessage {" + "  required group v (VARIANT(1)) {" + "    required binary value;" + "    required binary metadata;" + "  }" + "}", rc -> {
        rc.startMessage();
        rc.startField("v", 0);
        rc.startGroup();
        rc.startField("value", 0);
        rc.addBinary(expectedValue);
        rc.endField("value", 0);
        rc.startField("metadata", 1);
        rc.addBinary(expectedMetadata);
        rc.endField("metadata", 1);
        rc.endGroup();
        rc.endField("v", 0);
        rc.endMessage();
    });
    Schema variantSchema = record("v", field("metadata", Schema.create(Schema.Type.BYTES)), field("value", Schema.create(Schema.Type.BYTES)));
    Schema expectedSchema = record("VariantMessage", field("v", variantSchema));
    GenericRecord expectedRecord = instance(expectedSchema, "v", instance(variantSchema, "metadata", expectedMetadata.toByteBuffer(), "value", expectedValue.toByteBuffer()));
    MessageType readSchema = MessageTypeParser.parseMessageType("message VariantMessage {" + "  required group v (VARIANT(1)) {" + "    required binary metadata;" + "    required binary value;" + "  }" + "}");
    Configuration conf = new Configuration();
    AvroReadSupport.setRequestedProjection(conf, avroSchema(readSchema));
    // both should behave the same way
    assertReaderContains(new AvroParquetReader(conf, test), expectedSchema, expectedRecord);
}

@Test
public void testShreddedScalar() throws Exception {
    runOneScalarTest("boolean", "", b -> b.appendBoolean(true), rc -> rc.addBoolean(true));
    // Test true and false, since they have different types in Variant.
    runOneScalarTest("boolean", "", b -> b.appendBoolean(false), rc -> rc.addBoolean(false));
    runOneScalarTest("boolean", "", b -> b.appendBoolean(false), rc -> rc.addBoolean(false));
    runOneScalarTest("int32", "(INT_8)", b -> b.appendByte((byte) 123), rc -> rc.addInteger(123));
    runOneScalarTest("int32", "(INT_16)", b -> b.appendShort((short) -12345), rc -> rc.addInteger(-12345));
    runOneScalarTest("int32", "(INT_32)", b -> b.appendInt(1234567890), rc -> rc.addInteger(1234567890));
    runOneScalarTest("int64", "", b -> b.appendLong(1234567890123L), rc -> rc.addLong(1234567890123L));
    runOneScalarTest("double", "", b -> b.appendDouble(1.2e34), rc -> rc.addDouble(1.2e34));
    runOneScalarTest("float", "", b -> b.appendFloat(1.2e34f), rc -> rc.addFloat(1.2e34f));
    runOneScalarTest("int32", "(DECIMAL(9, 2))", b -> b.appendDecimal(new BigDecimal("1.23")), rc -> rc.addInteger(123));
    runOneScalarTest("int64", "(DECIMAL(18, 5))", b -> b.appendDecimal(new BigDecimal("123456789.12345")), rc -> rc.addLong(12345678912345L));
    BigDecimal decimalVal = new BigDecimal("0.12345678901234567890123456789012345678");
    runOneScalarTest("fixed_len_byte_array(16)", "(DECIMAL(38, 38))", b -> b.appendDecimal(decimalVal), rc -> rc.addBinary(Binary.fromConstantByteArray(decimalVal.unscaledValue().toByteArray())));
    // Verify that the parquet type's scale is used when shredding, and not the scale implied by the value.
    runOneScalarTest("int32", "(DECIMAL(9, 2))", b -> b.appendDecimal(new BigDecimal("1.2").setScale(2)), rc -> rc.addInteger(120));
    runOneScalarTest("int64", "(DECIMAL(18, 5))", b -> b.appendDecimal(new BigDecimal("123456789").setScale(5)), rc -> rc.addLong(12345678900000L));
    BigDecimal decimalVal2 = new BigDecimal("9.12345678901234567890123456789").setScale(37);
    runOneScalarTest("fixed_len_byte_array(16)", "(DECIMAL(38, 37))", b -> b.appendDecimal(decimalVal2), rc -> rc.addBinary(Binary.fromConstantByteArray(decimalVal2.unscaledValue().toByteArray())));
    runOneScalarTest("int64", "(TIMESTAMP(MICROS, true))", b -> b.appendTimestampTz(123), rc -> rc.addLong(123));
    runOneScalarTest("int64", "(TIMESTAMP(MICROS, false))", b -> b.appendTimestampNtz(123), rc -> rc.addLong(123));
    runOneScalarTest("binary", "", b -> b.appendBinary(Binary.fromString("hello").toByteBuffer()), rc -> rc.addBinary(Binary.fromString("hello")));
    runOneScalarTest("binary", "(UTF8)", b -> b.appendString("hello"), rc -> rc.addBinary(Binary.fromString("hello")));
    runOneScalarTest("int64", "(TIME(MICROS, false))", b -> b.appendTime(123), rc -> rc.addLong(123));
    runOneScalarTest("int64", "(TIMESTAMP(NANOS, true))", b -> b.appendTimestampNanosTz(123), rc -> rc.addLong(123));
    runOneScalarTest("int64", "(TIMESTAMP(NANOS, false))", b -> b.appendTimestampNanosNtz(123), rc -> rc.addLong(123));
    UUID uuid = UUID.randomUUID();
    byte[] uuidBytes = new byte[16];
    ByteBuffer bb = ByteBuffer.wrap(uuidBytes, 0, 16).order(ByteOrder.BIG_ENDIAN);
    bb.putLong(uuid.getMostSignificantBits());
    bb.putLong(uuid.getLeastSignificantBits());
    runOneScalarTest("fixed_len_byte_array(16)", "(UUID)", b -> b.appendUUID(uuid), rc -> rc.addBinary(Binary.fromConstantByteArray(uuidBytes)));
