@Test
public void testArray() throws Exception {
    Variant testValue = fullVariant(b -> {
        VariantArrayBuilder ab = b.startArray();
        ab.appendLong(123);
        ab.appendString("Hello");
        ab.appendLong(456);
        b.endArray();
    });
    // The string value will be stored in `value` in Variant binary form.
    ByteBuffer stringValue = variant("Hello");
    Binary expectedValue = Binary.fromConstantByteBuffer(testValue.getValueBuffer());
    Binary expectedMetadata = Binary.fromConstantByteBuffer(testValue.getMetadataBuffer());
    Path test = writeDirect("message VariantMessage {" + "  required group v (VARIANT(1)) {" + "    required binary metadata;" + "    optional binary value;" + "    optional group typed_value (LIST) {" + "      repeated group list {" + "        required group element {" + "          optional int64 typed_value;" + "          optional binary value;" + "        }" + "      }" + "    }" + "  }" + "}", rc -> {
        rc.startMessage();
        rc.startField("v", 0);
        rc.startGroup();
        rc.startField("typed_value", 2);
        rc.startGroup();
        rc.startField("list", 0);
        rc.startGroup();
        rc.startField("element", 0);
        rc.startGroup();
        rc.startField("typed_value", 0);
        rc.addLong(123);
        rc.endField("typed_value", 0);
        rc.endGroup();
        rc.endField("element", 0);
        rc.endGroup();
        rc.startGroup();
        rc.startField("element", 0);
        rc.startGroup();
        rc.startField("value", 1);
        rc.addBinary(Binary.fromConstantByteBuffer(stringValue));
        rc.endField("value", 1);
        rc.endGroup();
        rc.endField("element", 0);
        rc.endGroup();
        rc.startGroup();
        rc.startField("element", 0);
        rc.startGroup();
        rc.startField("typed_value", 0);
        rc.addLong(456);
        rc.endField("typed_value", 0);
        rc.endGroup();
        rc.endField("element", 0);
        rc.endGroup();
        rc.endField("list", 0);
        rc.endGroup();
        rc.endField("typed_value", 2);
        rc.startField("metadata", 0);
        rc.addBinary(expectedMetadata);
        rc.endField("metadata", 0);
        rc.endGroup();
        rc.endField("v", 0);
        rc.endMessage();
    });
    Schema variantSchema = record("v", field("metadata", Schema.create(Schema.Type.BYTES)), field("value", Schema.create(Schema.Type.BYTES)));
    Schema expectedSchema = record("VariantMessage", field("v", variantSchema));
    GenericRecord expectedRecord = instance(expectedSchema, "v", instance(variantSchema, "metadata", expectedMetadata.toByteBuffer(), "value", expectedValue.toByteBuffer()));
    // both should behave the same way
    assertReaderContains(new AvroParquetReader(new Configuration(), test), expectedSchema, expectedRecord);
}

