public void testParsesSpecificDataModel() throws IOException {
    // SpecificRecord contains a logical type and will fail to decode unless its SpecificData model is parsed
    List<LogicalTypesTest> records = IntStream.range(0, 25).mapToObj(i -> LogicalTypesTest.newBuilder().setTimestamp(Instant.now()).setLocalDateTime(LocalDateTimeTest.newBuilder().setDate(LocalDate.now()).setTime(LocalTime.now()).build()).build()).collect(Collectors.toList());
    // Test that SpecificData model is parsed in AvroParquetWriter
    File tmp = File.createTempFile(getClass().getSimpleName(), ".tmp");
