    tmp.delete();
    Path path = new Path(tmp.getPath());
    try (ParquetWriter<LogicalTypesTest> writer = AvroParquetWriter.<LogicalTypesTest>builder(path).withSchema(LogicalTypesTest.getClassSchema()).withConf(new Configuration(false)).withCompressionCodec(CompressionCodecName.UNCOMPRESSED).build()) {
        for (LogicalTypesTest record : records) {
            writer.write(record);
        }
    }
    // Test that SpecificData model is parsed in AvroParquetReader
    final List<LogicalTypesTest> output = new ArrayList<>();
