@Test
public void testPageSize() {
    MessageType schema = Types.buildMessage().requiredList().requiredElement(BINARY).named("binary_col").requiredList().requiredElement(INT32).named("int32_col").named("msg");
    MemPageStore memPageStore = new MemPageStore(123);
    // Using V2 pages so we have rowCount info
    ColumnWriteStore writeStore = new ColumnWriteStoreV2(schema, memPageStore, ParquetProperties.builder().withPageSize(// Less than 10 records for binary_col
    1024).withMinRowCountForPageSizeCheck(// Enforce having precise page sizing
    1).withPageRowCountLimit(10).withDictionaryEncoding(// Enforce having large binary_col pages
    false).build());
    ColumnDescriptor binaryCol = schema.getColumnDescription(new String[] { "binary_col", "list", "element" });
    ColumnWriter binaryColWriter = writeStore.getColumnWriter(binaryCol);
    ColumnDescriptor int32Col = schema.getColumnDescription(new String[] { "int32_col", "list", "element" });
    ColumnWriter int32ColWriter = writeStore.getColumnWriter(int32Col);
    // Writing 123 records
    for (int i = 0; i < 123; ++i) {
        // Writing 10 values per record
        for (int j = 0; j < 10; ++j) {
            binaryColWriter.write(Binary.fromString("aaaaaaaaaaaa"), j == 0 ? 0 : binaryCol.getMaxRepetitionLevel(), binaryCol.getMaxDefinitionLevel());
            int32ColWriter.write(42, j == 0 ? 0 : int32Col.getMaxRepetitionLevel(), int32Col.getMaxDefinitionLevel());
        }
        writeStore.endRecord();
    }
    writeStore.flush();
    // Check that all the binary_col pages are <= 1024 bytes
    {
        PageReader binaryColPageReader = memPageStore.getPageReader(binaryCol);
        assertEquals(1230, binaryColPageReader.getTotalValueCount());
        int pageCnt = 0;
        int valueCnt = 0;
        while (valueCnt < binaryColPageReader.getTotalValueCount()) {
            DataPage page = binaryColPageReader.readPage();
            ++pageCnt;
            valueCnt += page.getValueCount();
            LOG.info("binary_col page-{}: {} bytes, {} rows", pageCnt, page.getCompressedSize(), page.getIndexRowCount().get());
            assertTrue("Compressed size should be less than 1024", page.getCompressedSize() <= 1024);
        }
    }
    // Check that all the int32_col pages contain <= 10 rows
    {
        PageReader int32ColPageReader = memPageStore.getPageReader(int32Col);
        assertEquals(1230, int32ColPageReader.getTotalValueCount());
        int pageCnt = 0;
        int valueCnt = 0;
        while (valueCnt < int32ColPageReader.getTotalValueCount()) {
            DataPage page = int32ColPageReader.readPage();
            ++pageCnt;
            valueCnt += page.getValueCount();
            LOG.info("int32_col page-{}: {} bytes, {} rows", pageCnt, page.getCompressedSize(), page.getIndexRowCount().get());
            assertTrue("Row count should be less than 10", page.getIndexRowCount().get() <= 10);
        }
    }
}

@Test
public void test() throws IOException {
    MemPageStore memPageStore = new MemPageStore(10);
    ColumnDescriptor col = new ColumnDescriptor(path, PrimitiveTypeName.INT64, 2, 2);
    LongStatistics stats = new LongStatistics();
    PageWriter pageWriter = memPageStore.getPageWriter(col);
    pageWriter.writePage(BytesInput.from(new byte[735]), 209, stats, BIT_PACKED, BIT_PACKED, PLAIN);
    pageWriter.writePage(BytesInput.from(new byte[743]), 209, stats, BIT_PACKED, BIT_PACKED, PLAIN);
    pageWriter.writePage(BytesInput.from(new byte[743]), 209, stats, BIT_PACKED, BIT_PACKED, PLAIN);
    pageWriter.writePage(BytesInput.from(new byte[735]), 209, stats, BIT_PACKED, BIT_PACKED, PLAIN);
    PageReader pageReader = memPageStore.getPageReader(col);
    long totalValueCount = pageReader.getTotalValueCount();
    LOG.info("Total value count: " + totalValueCount);
    assertEquals("Expected total value count to be 836 (4 pages * 209 values)", 836, totalValueCount);
    int total = 0;
    int pageCount = 0;
    do {
        DataPage readPage = pageReader.readPage();
        // Assert page was successfully read
        assertNotNull("Page should not be null", readPage);
        // Assert page has expected value count
        assertEquals("Each page should have 209 values", 209, readPage.getValueCount());
        // Assert encodings when the implementation is DataPageV1
        assertTrue("Page should be an instance of DataPageV1", readPage instanceof DataPageV1);
        if (readPage instanceof DataPageV1) {
            DataPageV1 v1 = (DataPageV1) readPage;
            assertEquals("Page repetition level encoding should be BIT_PACKED", BIT_PACKED, v1.getRlEncoding());
            assertEquals("Page definition level encoding should be BIT_PACKED", BIT_PACKED, v1.getDlEncoding());
            assertEquals("Page value encoding should be PLAIN", PLAIN, v1.getValueEncoding());
        }
        total += readPage.getValueCount();
        pageCount++;
    } while (total < totalValueCount);
    // Assert we read exactly the expected number of pages and values
    assertEquals("Should have read 4 pages", 4, pageCount);
    assertEquals("Total values read should match totalValueCount", totalValueCount, total);
}

