@Test
public void testXxHashCorrectness() {
    byte[] data = new byte[32];
    for (int i = 0; i < data.length; i++) {
        data[i] = (byte) i;
        ByteBuffer input = ByteBuffer.wrap(data, 0, i).order(ByteOrder.nativeOrder());
        assertEquals(HASHES_OF_LOOPING_BYTES_WITH_SEED_0[i], LongHashFunction.xx(0).hashBytes(input));
        assertEquals(HASHES_OF_LOOPING_BYTES_WITH_SEED_42[i], LongHashFunction.xx(42).hashBytes(input));
    }
}

@Test
public void testFloatPipeline() throws Exception {
    // Generate random data.
    Random rand = new Random(1337);
    final int numElements = 1024;
    float[] values = new float[numElements];
    for (int i = 0; i < numElements; ++i) {
        float f = rand.nextFloat() * 4096.0f;
        values[i] = f;
    }
    ByteStreamSplitValuesWriter.FloatByteStreamSplitValuesWriter writer = null;
    try {
        // Encode data.
        writer = new ByteStreamSplitValuesWriter.FloatByteStreamSplitValuesWriter(numElements * 4, numElements * 4, new DirectByteBufferAllocator());
        for (float v : values) {
            writer.writeFloat(v);
        }
        assertEquals(numElements * 4, writer.getBufferedSize());
        BytesInput input = writer.getBytes();
        assertEquals(numElements * 4, input.size());
        ByteStreamSplitValuesReaderForFloat reader = new ByteStreamSplitValuesReaderForFloat();
        reader.initFromPage(numElements, ByteBufferInputStream.wrap(input.toByteBuffer()));
        for (float expectedValue : values) {
            float newValue = reader.readFloat();
            assertEquals(expectedValue, newValue, 0.0f);
        }
    } finally {
        if (writer != null) {
            writer.reset();
            writer.close();
        }
    }
}

