@Test
public void testContainsCreation() {
    assertThrows("Contains predicate does not support null element value", IllegalArgumentException.class, () -> contains(eq(binColumn, null)));
    // Assert that a single Contains predicate referencing multiple columns throws an error
    assertThrows("Composed Contains predicates must reference the same column name; found [a.b.c, b.c.d]", IllegalArgumentException.class, () -> contains(eq(binaryColumn("a.b.c"), Binary.fromString("foo"))).and(contains(eq(binaryColumn("b.c.d"), Binary.fromString("bar")))).and(contains(eq(binaryColumn("b.c.d"), Binary.fromString("bar")))));
    // Assert that a Contains predicate referencing multiple columns is allowed when composed with and() or or()
    final FilterPredicate rewritten = ContainsRewriter.rewrite(or(contains(eq(binaryColumn("a.b.c"), Binary.fromString("foo"))), and(contains(eq(binaryColumn("b.c.d"), Binary.fromString("bar"))), contains(eq(binaryColumn("b.c.d"), Binary.fromString("baz"))))));
    assertTrue(rewritten instanceof Or);
    // Assert that the predicates for column b.c.d have been combined into a single Contains predicate,
    // while the predicate for column a.b.c is separate
    final Or or = (Or) rewritten;
    assertEquals(binaryColumn("a.b.c"), ((Operators.Contains) or.getLeft()).getColumn());
    assertEquals(binaryColumn("b.c.d"), ((Operators.Contains) or.getRight()).getColumn());
}

