@Test
public void testFloat16ToFloat() {
    // Zeroes
    assertEquals(0.0f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { 0x00, 0x00 })), 0.0f);
    assertEquals(-0.0f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0x80 })), 0.0f);
    // NaN
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xc0, (byte) 0x7f })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0x7e })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0x7f })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0xfe })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0xff })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x7f, (byte) 0x7e })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x7f, (byte) 0xfe })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0xfe })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0x7f })), 0.0f);
    assertEquals(Float.NaN, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0xff })), 0.0f);
    // infinities
    assertEquals(Float.POSITIVE_INFINITY, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0x7c })), 0.0f);
    assertEquals(Float.NEGATIVE_INFINITY, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0xfc })), 0.0f);
    // subnormals
    assertEquals(5.9604645E-8f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x01, (byte) 0x00 })), 0.0f);
    assertEquals(-65504.0f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0xfb })), 0.0f);
    assertEquals(+65504.0f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0x7b })), 0.0f);
    assertEquals(-6.097555E-5f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0xff, (byte) 0x83 })), 0.0f);
    assertEquals(-5.9604645E-8f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x01, (byte) 0x80 })), 0.0f);
    // Known values
    assertEquals(1.0009765625f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x01, (byte) 0x3c })), 0.0f);
    assertEquals(-2.0f, Float16.toFloat(Binary.fromConstantByteArray(new byte[] { (byte) 0x00, (byte) 0xc0 })), 0.0f);
