    assertEquals(1, Float16.compare(NaN, POSITIVE_INFINITY));
    assertEquals(-1, Float16.compare(POSITIVE_INFINITY, NaN));
    assertEquals(0, Float16.compare(POSITIVE_INFINITY, POSITIVE_INFINITY));
