    // maximum precision for 8 bytes is 19
    assertThrows("should reject precision 19 with length 8", IllegalStateException.class, (Callable<Type>) () -> Types.required(FIXED_LEN_BYTE_ARRAY).length(8).as(DECIMAL).precision(19).scale(4).named("aDecimal"));
    assertThrows("should reject precision 19 with length 8", IllegalStateException.class, (Callable<Type>) () -> Types.required(INT64).length(8).as(DECIMAL).precision(19).scale(4).named("aDecimal"));
