    // Test composed contains() with not(contains())
    assertPredicate(and(not(contains(eq(binaryColumn("phoneNumbers.phone.kind"), Binary.fromString("cell")))), or(contains(eq(binaryColumn("phoneNumbers.phone.kind"), Binary.fromString("home"))), contains(eq(binaryColumn("phoneNumbers.phone.kind"), Binary.fromString("business"))))), 28L, 30L, 31L);
