        file.delete();
        Path path = new Path(file.getAbsolutePath());
        try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(path).withAllocator(allocator).withPageRowCountLimit(10).withConf(conf).withDictionaryEncoding(false).withBloomFilterEnabled("name", true).withBloomFilterNDV("name", buildBloomFilterCount).withBloomFilterFPP("name", testFpp).build()) {
            for (String str : distinctStringsForFileGenerate) {
                writer.write(factory.newGroup().append("name", str));
            }
        }
        try (ParquetFileReader reader = ParquetFileReader.open(HadoopInputFile.fromPath(path, new Configuration()))) {
            BlockMetaData blockMetaData = reader.getFooter().getBlocks().get(0);
            BloomFilter bloomFilter = reader.getBloomFilterDataReader(blockMetaData).readBloomFilter(blockMetaData.getColumns().get(0));
            // The false positive counts the number of times FindHash returns true.
            int falsePositive = 0;
            Set<String> distinctStringsForProbe = new HashSet<>();
            while (distinctStringsForProbe.size() < testBloomFilterCount) {
                String str = RandomStringUtils.randomAlphabetic(randomStrLen - 1);
                if (distinctStringsForProbe.add(str) && bloomFilter.findHash(LongHashFunction.xx(0).hashBytes(Binary.fromString(str).toByteBuffer()))) {
                    falsePositive++;
                }
            }
            // The false positive should be less than totalCount * fpp. Add 15% here for error space.
            double expectedFalsePositiveMaxCount = Math.floor(testBloomFilterCount * (testFpp * 1.15));
            assertTrue(falsePositive < expectedFalsePositiveMaxCount && falsePositive > 0);
        }
    }
}

