@Test
public void testSizeStatisticsAndStatisticsControl() throws Exception {
    MessageType schema = Types.buildMessage().required(BINARY).named("string_field").required(BOOLEAN).named("boolean_field").required(INT32).named("int32_field").named("test_schema");
    SimpleGroupFactory factory = new SimpleGroupFactory(schema);
    // Create test data
    Group group = factory.newGroup().append("string_field", "test").append("boolean_field", true).append("int32_field", 42);
    // Test global disable
    File file = temp.newFile();
    temp.delete();
    Path path = new Path(file.getAbsolutePath());
    try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(path).withType(schema).withSizeStatisticsEnabled(false).withStatisticsEnabled(// Disable column statistics globally
    false).build()) {
        writer.write(group);
    }
    try (ParquetFileReader reader = ParquetFileReader.open(HadoopInputFile.fromPath(path, new Configuration()))) {
        // Verify size statistics are disabled globally
        for (BlockMetaData block : reader.getFooter().getBlocks()) {
            for (ColumnChunkMetaData column : block.getColumns()) {
                // Make sure there is no column statistics
                assertTrue(column.getStatistics().isEmpty());
                assertNull(column.getSizeStatistics());
            }
        }
    }
    // Test column-specific control
    file = temp.newFile();
    temp.delete();
    path = new Path(file.getAbsolutePath());
    try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(path).withType(schema).withSizeStatisticsEnabled(// enable globally
    true).withSizeStatisticsEnabled("boolean_field", // disable for specific column
    false).withStatisticsEnabled("boolean_field", // disable column statistics
    false).build()) {
        writer.write(group);
    }
    try (ParquetFileReader reader = ParquetFileReader.open(HadoopInputFile.fromPath(path, new Configuration()))) {
        // Verify size statistics are enabled for all columns except boolean_field
        for (BlockMetaData block : reader.getFooter().getBlocks()) {
            for (ColumnChunkMetaData column : block.getColumns()) {
                if (column.getPath().toDotString().equals("boolean_field")) {
                    assertNull(column.getSizeStatistics());
                    assertTrue(column.getStatistics().isEmpty());
                } else {
                    assertTrue(column.getSizeStatistics().isValid());
                    assertFalse(column.getStatistics().isEmpty());
                }
            }
        }
    }
}

