@Test
public void TestSnappyStream() throws IOException {
    SnappyCodec codec = new SnappyCodec();
    codec.setConf(new Configuration());
    int blockSize = 1024;
    int inputSize = blockSize * 1024;
    byte[] input = new byte[inputSize];
    for (int i = 0; i < inputSize; ++i) {
        input[i] = (byte) i;
    }
    ByteArrayOutputStream compressedStream = new ByteArrayOutputStream();
    CompressionOutputStream compressor = codec.createOutputStream(compressedStream);
    int bytesCompressed = 0;
    while (bytesCompressed < inputSize) {
        int len = Math.min(inputSize - bytesCompressed, blockSize);
        compressor.write(input, bytesCompressed, len);
        bytesCompressed += len;
    }
    compressor.finish();
    byte[] rawCompressed = Snappy.compress(input);
    byte[] codecCompressed = compressedStream.toByteArray();
    // Validate that the result from the codec is the same as if we compressed the
    // buffer directly.
    assertArrayEquals(rawCompressed, codecCompressed);
    ByteArrayInputStream inputStream = new ByteArrayInputStream(codecCompressed);
    CompressionInputStream decompressor = codec.createInputStream(inputStream);
    byte[] codecDecompressed = new byte[inputSize];
    int bytesDecompressed = 0;
    int numBytes;
    while ((numBytes = decompressor.read(codecDecompressed, bytesDecompressed, blockSize)) != 0) {
        bytesDecompressed += numBytes;
        if (bytesDecompressed == inputSize)
            break;
    }
    byte[] rawDecompressed = Snappy.uncompress(rawCompressed);
    assertArrayEquals(input, rawDecompressed);
    assertArrayEquals(input, codecDecompressed);
}

@Test
public void testStoreBloomFilter() throws IOException {
    try (TrackingByteBufferAllocator allocator = TrackingByteBufferAllocator.wrap(new HeapByteBufferAllocator());
        ParquetFileReader reader = new ParquetFileReader(HadoopInputFile.fromPath(file, new Configuration()), ParquetReadOptions.builder().withAllocator(allocator).build())) {
        List<BlockMetaData> blocks = reader.getRowGroups();
        blocks.forEach(block -> {
            try {
                // column `id` isn't fully encoded in dictionary, it will generate `BloomFilter`
                ColumnChunkMetaData idMeta = block.getColumns().get(0);
                EncodingStats idEncoding = idMeta.getEncodingStats();
                Assert.assertTrue(idEncoding.hasNonDictionaryEncodedPages());
                Assert.assertNotNull(reader.readBloomFilter(idMeta));
                // column `name` is fully encoded in dictionary, it won't generate `BloomFilter`
                ColumnChunkMetaData nameMeta = block.getColumns().get(1);
                EncodingStats nameEncoding = nameMeta.getEncodingStats();
                Assert.assertFalse(nameEncoding.hasNonDictionaryEncodedPages());
                Assert.assertNull(reader.readBloomFilter(nameMeta));
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }
}

@Test
public void testZstdCodec() throws IOException {
