    try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(new LocalOutputFile(path)).withConf(conf).withDictionaryEncoding(false).build()) {
        for (Binary value : points) {
            writer.write(factory.newGroup().append("geometry", value));
        }
