@Test
public void testBinaryColumnSizeStatistics() throws IOException {
    MessageType schema = Types.buildMessage().optional(PrimitiveType.PrimitiveTypeName.BINARY).as(LogicalTypeAnnotation.stringType()).named("name").named("msg");
    Configuration conf = new Configuration();
